ALTER TABLE "asset_jobs" ADD CONSTRAINT "asset_jobs_failure_code_value_check" CHECK ("asset_jobs"."failure_code" IS NULL OR "asset_jobs"."failure_code" IN ('UPLOAD_EXPIRED', 'MEDIA_TOO_LARGE', 'MEDIA_LIMIT_EXCEEDED', 'MEDIA_TYPE_MISMATCH', 'UNSUPPORTED_MEDIA', 'INVALID_MEDIA', 'UNSAFE_MEDIA_URL', 'MEDIA_SOURCE_UNAVAILABLE', 'PROCESSING_UNAVAILABLE'));